<?php
declare(strict_types=1);require_once __DIR__.'/includes/functions.php';$s=db()->prepare("SELECT p.*,c.name category_name,u.display_name author_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN users u ON u.id=p.author_id WHERE p.slug=? AND p.status='published' AND p.published_at<=NOW() LIMIT 1");$s->execute([trim($_GET['slug']??'')]);$p=$s->fetch();if(!$p){http_response_code(404);$pageTitle='Материал не найден';include __DIR__.'/includes/header.php';echo '<section class="article-page"><h1>404</h1><p class="dek">Такой публикации нет или она ещё не вышла.</p></section>';include __DIR__.'/includes/footer.php';exit;}$pageTitle=$p['title'].' — '.APP_NAME;$pageDescription=$p['excerpt']?:excerpt($p['content']);include __DIR__.'/includes/header.php';?><article class="article-page"><span class="section-label"><?=e($p['category_name']??'Материал')?></span><h1><?=e($p['title'])?></h1><?php if($p['excerpt']):?><p class="dek"><?=e($p['excerpt'])?></p><?php endif;?><div class="meta"><span>Автор: <?=e($p['author_name']??'Редакция')?></span><span><?=e(format_date($p['published_at']))?></span></div><?php if($p['image_url']):?><img class="story-image" src="<?=e($p['image_url'])?>" alt="<?=e($p['title'])?>"><?php endif;?><div class="article-body"><?=$p['content']?></div></article><?php include __DIR__.'/includes/footer.php';?>
